pub fn dimensionXml(mut in_txt: Tpl::Text, in_a_d: &metamodelica::Ref<DAE::Dimension>) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_d {
        Deref @ DAE::Dimension::DIM_INTEGER { integer: i_integer, .. } => {
            let mut txt = in_txt;
            txt = Tpl::writeStr(txt, intString(*i_integer))?;
            Ok(txt)
        }
        Deref @ DAE::Dimension::DIM_ENUM { size: i_size, .. } => {
            let mut txt = in_txt;
            txt = Tpl::writeStr(txt, intString(*i_size))?;
            Ok(txt)
        }
        Deref @ DAE::Dimension::DIM_UNKNOWN { .. } => {
            let mut txt = in_txt;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(":") }))?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("INVALID_DIMENSION") }))?;
            Ok(txt)
        }
        _ => Err("dimensionXml: no case matched"),
    } }
}

pub fn assertCommonXml(
    mut txt: Tpl::Text,
    a_condition: &metamodelica::Ref<DAE::Exp>,
    a_message: &metamodelica::Ref<DAE::Exp>,
    a_context: &SimCodeFunction::Context,
    mut a_varDecls: Tpl::Text,
    a_info: &SourceInfo,
) -> Result<(Tpl::Text, Tpl::Text)> {
    let mut l_preExpCond;
    let mut l_preExpMsg;
    let mut l_condVar;
    let mut out_a_varDecls;
    let mut l_msgVar;
    let mut out_txt;
    l_preExpCond = (*Tpl::emptyTxt).clone();
    l_preExpMsg = (*Tpl::emptyTxt).clone();
    (l_condVar, l_preExpCond, out_a_varDecls) = daeExpXml(
        (*Tpl::emptyTxt).clone(),
        a_condition,
        a_context,
        l_preExpCond,
        a_varDecls,
    )?;
    (l_msgVar, l_preExpMsg, out_a_varDecls) = daeExpXml(
        (*Tpl::emptyTxt).clone(),
        a_message,
        a_context,
        l_preExpMsg,
        out_a_varDecls,
    )?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("<fun:Assertion>\n"), literal!("  <fun:Condition>\n")],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 4 }))?;
    out_txt = Tpl::writeText(out_txt, l_condVar)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("  </fun:Condition>\n"), literal!("  <fun:Message>\n")],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 4 }))?;
    out_txt = Tpl::writeText(out_txt, l_msgVar)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("  </fun:Message>\n"), literal!("</fun:Assertion>")],
            lastHasNewLine: false,
        }),
    )?;
    Ok((out_txt, out_a_varDecls))
}

pub fn error(mut txt: Tpl::Text, a_srcInfo: &SourceInfo, a_errMessage: &ArcStr) -> Result<Tpl::Text> {
    let mut out_txt;
    let mut ret_0;
    Tpl::addSourceTemplateError(a_errMessage.clone(), a_srcInfo)?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("\n"), literal!("#error \"")],
            lastHasNewLine: false,
        }),
    )?;
    ret_0 = Error::infoStr(a_srcInfo)?;
    out_txt = Tpl::writeStr(out_txt, ret_0)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" ") }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_errMessage.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("\"") }),
    )?;
    out_txt = Tpl::writeTok(out_txt, metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE))?;
    Ok(out_txt)
}
